import test from 'node:test';import assert from 'node:assert/strict';import { createState, step, RUN_ACCEL, AIR_CONTROL, DT } from '../../src/physics.js';test('air control reduces acceleration', async t => {
  const level = { platforms: [], coins: [], goal: { min: [0,0,0], max: [0,0,0] }, killY: -100, spawn: [0,0,0] };
  let state = createState(level);
  state.grounded = false;
  state.vel = [0, 0, 0];
  const input = { x: 1, z: 0, jump: false };
  const next = step(state, input, level, 0);
  const expectedAccel = RUN_ACCEL * AIR_CONTROL * DT;
  assert.strictEqual(next.vel[0], expectedAccel);
  assert.strictEqual(next.vel[2], 0);
});

