import test from 'node:test';import assert from 'node:assert/strict';import { createState, step } from '../../src/physics.js';test('triggers respawn when below killY', async t => {
  const level = { platforms: [], coins: [], goal: { min: [0,0,0], max: [0,0,0] }, killY: -12, spawn: [5, 10, 3] };
  let state = createState(level);
  state.pos = [5, -13, 3];
  state.vel = [0, 0, 0];
  state.grounded = false;
  state.deaths = 2;
  const input = { x: 0, z: 0, jump: false };
  const next = step(state, input, level, 0);
  assert.strictEqual(next.deaths, 3);
  assert.deepStrictEqual(next.pos, level.spawn);
  assert.strictEqual(next.vel[0], 0);
  assert.strictEqual(next.vel[1], 0);
  assert.strictEqual(next.vel[2], 0);
  assert.strictEqual(next.grounded, true);
});

